        map["Selection updates when switching screens. Sensors with active alerts are polled in all modes even when not visible, as long as they are enabled in Sensors. Full ECU scanning remains available in Vehicle."] = "Die Auswahl wird beim Bildschirmwechsel aktualisiert. Sensoren mit aktiven Warnungen werden in allen Modi abgefragt, auch wenn sie nicht sichtbar sind, sofern sie unter Sensoren aktiviert sind. Der vollständige ECU-Scan bleibt unter Fahrzeug verfügbar."
        map["Al cambiar de pantalla se actualiza la selección. Los sensores con avisos activados se consultan en todos los modos aunque no estén visibles, siempre que estén habilitados en Sensores. El escaneo completo de la ECU sigue disponible en Vehículo."] = "Die Auswahl wird beim Bildschirmwechsel aktualisiert. Sensoren mit aktiven Warnungen werden in allen Modi abgefragt, auch wenn sie nicht sichtbar sind, sofern sie unter Sensoren aktiviert sind. Der vollständige ECU-Scan bleibt unter Fahrzeug verfügbar."
