        map["Android stopped the service. Open the app to resume reading."] = "Android hat den Dienst beendet. Öffne die App, um die Messung fortzusetzen."
        map["Android detuvo el servicio. Abre la app para reanudar la lectura."] = "Android hat den Dienst beendet. Öffne die App, um die Messung fortzusetzen."
        map["Android does not expose a Bluetooth adapter to this app. Use WiFi if your head unit only allows Bluetooth from its factory app."] = "Android stellt dieser App keinen Bluetooth-Adapter zur Verfügung. Nutze WiFi, falls dein Autoradio Bluetooth nur über die Werks-App zulässt."
        map["Android no ofrece un adaptador Bluetooth a esta app. Usa WiFi si la radio solo permite Bluetooth desde su app de fábrica."] = "Android stellt dieser App keinen Bluetooth-Adapter zur Verfügung. Nutze WiFi, falls dein Autoradio Bluetooth nur über die Werks-App zulässt."
        map["Android could not start discovery. Check Bluetooth and, on Android 6–11, system Location."] = "Android konnte die Suche nicht starten. Prüfe Bluetooth und unter Android 6–11 den Systemstandort."
        map["Android no pudo iniciar la búsqueda. Comprueba Bluetooth y, en Android 6–11, la ubicación del sistema."] = "Android konnte die Suche nicht starten. Prüfe Bluetooth und unter Android 6–11 den Systemstandort."
        map["Android requires nearby devices and location permissions (Android 6–11 only) to discover and pair Bluetooth (SPP) and Wi-Fi ELM327 adapters. On Android 12+, neverForLocation is declared. The app NEVER tracks, reads or stores your geographic location."] = "Android benötigt Berechtigungen für Geräte in der Nähe und den Standort (nur Android 6–11), um Bluetooth- (SPP) und Wi-Fi-ELM327-Adapter zu finden und zu koppeln. Ab Android 12+ ist neverForLocation deklariert. Die App verfolgt, liest oder speichert NIEMALS deinen geografischen Standort."
        map["Android requiere permisos de dispositivos cercanos y localización (solo en Android 6–11) para detectar y emparejar adaptadores ELM327 Bluetooth (SPP) y Wi-Fi. En Android 12+ se declara neverForLocation. La aplicación NUNCA rastrea, lee ni almacena tu ubicación geográfica."] = "Android benötigt Berechtigungen für Geräte in der Nähe und den Standort (nur Android 6–11), um Bluetooth- (SPP) und Wi-Fi-ELM327-Adapter zu finden und zu koppeln. Ab Android 12+ ist neverForLocation deklariert. Die App verfolgt, liest oder speichert NIEMALS deinen geografischen Standort."
        map["Android automatically backs up your vehicles, custom dashboards, sensors, alerts and language to Google Drive. You can also export or import a JSON file to transfer your setup to an Android car head unit without a Google account."] = "Android sichert deine Fahrzeuge, benutzerdefinierten Dashboards, Sensoren, Warnungen und Spracheinstellungen automatisch in Google Drive. Du kannst auch eine JSON-Datei exportieren oder importieren, um deine Konfiguration auf ein Android-Autoradio ohne Google-Konto zu übertragen."
        map["Android respalda automáticamente tus vehículos, pantallas a medida, sensores, avisos e idioma en Google Drive. También puedes exportar o importar un archivo JSON para transferir tu configuración a una radio Android de coche sin cuenta de Google."] = "Android sichert deine Fahrzeuge, benutzerdefinierten Dashboards, Sensoren, Warnungen und Spracheinstellungen automatisch in Google Drive. Du kannst auch eine JSON-Datei exportieren oder importieren, um deine Konfiguration auf ein Android-Autoradio ohne Google-Konto zu übertragen."
        map["Record the conditions, review freeze frame data and consult the manufacturer service procedure before repairing. The same condition may have multiple causes."] = "Notiere die Bedingungen, prüfe die Freeze-Frame-Daten und ziehe vor einer Reparatur die Reparaturanleitung des Herstellers hinzu. Dieselbe Bedingung kann mehrere Ursachen haben."
        map["Anota las condiciones, revisa los datos congelados y consulta el procedimiento del fabricante antes de reparar. La misma condición puede tener varias causas."] = "Notiere die Bedingungen, prüfe die Freeze-Frame-Daten und ziehe vor einer Reparatur die Reparaturanleitung des Herstellers hinzu. Dieselbe Bedingung kann mehrere Ursachen haben."
