        map["La app recuerda el último adaptador Bluetooth o WiFi conectado y vuelve a intentarlo mientras no esté disponible. Puedes elegir otro desde la pestaña Conexión. Desconectar detiene los intentos hasta que selecciones un adaptador o vuelvas a abrir la app."] = "Die App merkt sich den zuletzt verbundenen Bluetooth- oder WLAN-Adapter und versucht es erneut, solange er nicht verfügbar ist. Im Tab Verbindung können Sie einen anderen auswählen. Das Trennen beendet die Versuche, bis Sie einen Adapter auswählen oder die App neu öffnen."
