        map["To connect a physical ELM327:\n1. Plug it into the vehicle's OBD-II port.\n2. Turn the vehicle ignition to ON.\n3. Pair the adapter in your device's Bluetooth Settings (common PIN: 1234 or 0000).\n4. Return to this app.\nIf the ELM327 only appears in the head unit's factory app and not here, its Bluetooth stack may be restricted; try a WiFi ELM327."] = "So verbinden Sie einen physischen ELM327:\n1. Stecken Sie ihn in die OBD-II-Buchse des Fahrzeugs.\n2. Schalten Sie die Zündung des Fahrzeugs ein (ON).\n3. Koppeln Sie den Adapter in den Bluetooth-Einstellungen Ihres Geräts (übliche PIN: 1234 oder 0000).\n4. Kehren Sie zu dieser App zurück.\nWenn der ELM327 nur in der Werks-App des Radios und nicht hier erscheint, ist dessen Bluetooth-Stack möglicherweise eingeschränkt; versuchen Sie einen WLAN-ELM327."
