        map["OBD Mode 04 will be sent to emissions ECUs. This clears stored and pending codes, freeze frame data and readiness monitors. Permanent codes remain until the ECU verifies the repair."] = "OBD-Modus 04 wird an die Emissionssteuergeräte gesendet. Dadurch werden gespeicherte und ausstehende Fehlercodes, Freeze-Frame-Daten und Bereitschaftsmonitore gelöscht. Permanente Codes bleiben bestehen, bis das Steuergerät die Reparatur bestätigt."
        map["Se enviará el modo OBD 04 a las ECU de emisiones. Borra códigos almacenados y pendientes, datos congelados y el estado de los monitores. Los permanentes permanecen hasta que la ECU verifica la reparación."] = "OBD-Modus 04 wird an die Emissionssteuergeräte gesendet. Dadurch werden gespeicherte und ausstehende Fehlercodes, Freeze-Frame-Daten und Bereitschaftsmonitore gelöscht. Permanente Codes bleiben bestehen, bis das Steuergerät die Reparatur bestätigt."
        map["Grids, layout density, assigned sensors, types, titles, colors, scales and decimals are saved. Live readings and adapter settings are not included in the file."] = "Raster, Anzeigedichte, zugewiesene Sensoren, Typen, Titel, Farben, Skalen und Dezimalstellen werden gespeichert. Live-Messwerte und Adaptereinstellungen sind nicht in der Datei enthalten."
        map["Se guardan rejillas, presentación, sensores asignados, tipos, títulos, colores, escalas y decimales. Las lecturas y la configuración del adaptador quedan fuera del archivo."] = "Raster, Anzeigedichte, zugewiesene Sensoren, Typen, Titel, Farben, Skalen und Dezimalstellen werden gespeichert. Live-Messwerte und Adaptereinstellungen sind nicht in der Datei enthalten."
        map["Every reading received from all enabled sensors will be saved along with its unit, equation and source. The CSV also logs disconnects and reconnects."] = "Jeder empfangene Messwert aller aktivierten Sensoren wird zusammen mit Einheit, Formel und Quelle gespeichert. Die CSV-Datei protokolliert auch Verbindungsabbrüche und Wiederverbindungen."
        map["Se guardará cada lectura recibida de todos los sensores habilitados, junto con su unidad, fórmula y origen. El CSV también registra los cortes y reconexiones."] = "Jeder empfangene Messwert aller aktivierten Sensoren wird zusammen mit Einheit, Formel und Quelle gespeichert. Die CSV-Datei protokolliert auch Verbindungsabbrüche und Wiederverbindungen."
